diff --git a/src/queue.js b/src/queue.js
index 18a0fc4..d4f0eb2 100644
--- a/src/queue.js
+++ b/src/queue.js
@@ -1 +1,170 @@
-export async function openQueue(options){throw new Error("NOT_IMPLEMENTED");}
+import { randomUUID } from 'node:crypto';
+
+const fail = (code, message = code) => Object.assign(new Error(message), { code });
+const obj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
+const validName = (v) => typeof v === 'string' && v.trim().length > 0;
+const clone = (v) => structuredClone(v);
+
+function jsonValue(value, seen = new Set()) {
+  if (value === null || typeof value === 'string' || typeof value === 'boolean') return true;
+  if (typeof value === 'number') return Number.isFinite(value);
+  if (typeof value !== 'object') return false;
+  if (seen.has(value)) return false;
+  seen.add(value);
+  const ok = Array.isArray(value)
+    ? value.every((item) => jsonValue(item, seen))
+    : (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null) && Object.keys(value).every((key) => jsonValue(value[key], seen));
+  seen.delete(value);
+  return ok;
+}
+
+function canonical(value) {
+  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
+  if (value && typeof value === 'object') return `{${Object.keys(value).sort().map((k) => `${JSON.stringify(k)}:${canonical(value[k])}`).join(',')}}`;
+  return JSON.stringify(value);
+}
+
+function publicJob(job) {
+  const { id, tenantId, key, payload, priority, status, attempts, createdAt, availableAt, workerId, leaseToken, leaseUntil, lastError } = job;
+  return clone({ id, tenantId, key, payload, priority, status, attempts, createdAt, availableAt, workerId, leaseToken, leaseUntil, lastError });
+}
+
+function validState(state) {
+  if (!obj(state) || state.schemaVersion !== 1 || !Array.isArray(state.jobs) || !Array.isArray(state.keys) || !Array.isArray(state.tokens) || !Number.isSafeInteger(state.sequence) || state.sequence < 0) {
+    throw fail('CORRUPT_STORE');
+  }
+}
+
+export async function openQueue(options) {
+  if (!obj(options)) throw fail('INVALID_INPUT');
+  const { store, now = Date.now, leaseMs = 1000, maxAttempts = 3, backoffMs = 100 } = options;
+  if (!obj(store) || typeof store.load !== 'function' || typeof store.compareAndSwap !== 'function' || typeof now !== 'function' ||
+      !Number.isSafeInteger(leaseMs) || leaseMs <= 0 || !Number.isSafeInteger(maxAttempts) || maxAttempts <= 0 ||
+      !Number.isSafeInteger(backoffMs) || backoffMs < 0) throw fail('INVALID_INPUT');
+
+  const time = () => now();
+  const validateArg = (arg) => { if (!obj(arg)) throw fail('INVALID_INPUT'); };
+  const validateTenant = (arg) => { validateArg(arg); if (!validName(arg.tenantId)) throw fail('INVALID_INPUT'); };
+
+  // Each retry starts from the latest detached snapshot; only a frozen-by-convention fresh tree goes to CAS.
+  async function transact(tenantId, action) {
+    for (let attempt = 0; attempt < 8; attempt += 1) {
+      let loaded;
+      try { loaded = await store.load(); } catch (e) { throw fail('STORAGE_ERROR', e?.message); }
+      let state;
+      if (loaded.state === null) state = { schemaVersion: 1, sequence: 0, jobs: [], keys: [], tokens: [] };
+      else {
+        validState(loaded.state);
+        try { state = clone(loaded.state); } catch { throw fail('CORRUPT_STORE'); }
+      }
+      const currentTime = time();
+      let changed = false;
+      for (const job of state.jobs) {
+        if (job.tenantId === tenantId && job.status === 'leased' && currentTime >= job.leaseUntil) {
+          job.status = job.attempts >= maxAttempts ? 'dead' : 'ready';
+          if (job.status === 'ready') job.availableAt = currentTime;
+          job.workerId = null; job.leaseToken = null; job.leaseUntil = null;
+          changed = true;
+        }
+      }
+      const outcome = action(state, currentTime);
+      if (outcome.changed) changed = true;
+      if (!changed) {
+        if (outcome.error) throw outcome.error;
+        return outcome.value;
+      }
+      try {
+        const committed = await store.compareAndSwap(loaded.version, state);
+        if (!committed) {
+          // A small jitter prevents simultaneous queue objects from repeatedly colliding in lockstep.
+          await new Promise((resolve) => setTimeout(resolve, Math.floor(Math.random() * (2 ** Math.min(attempt + 1, 6)) + 1)));
+          continue;
+        }
+      } catch (e) { throw fail('STORAGE_ERROR', e?.message); }
+      if (outcome.error) throw outcome.error;
+      return outcome.value;
+    }
+    throw fail('CONFLICT');
+  }
+
+  const find = (state, tenantId, id) => state.jobs.find((j) => j.tenantId === tenantId && j.id === id);
+  const leaseError = () => fail('STALE_LEASE');
+  return {
+    async enqueue(arg) {
+      validateTenant(arg);
+      const { tenantId, key, payload, priority = 0, delayMs = 0 } = arg;
+      if (!validName(key) || payload === null || typeof payload !== 'object' || !jsonValue(payload) || !Number.isSafeInteger(priority) || priority < -10 || priority > 10 || !Number.isSafeInteger(delayMs) || delayMs < 0) throw fail('INVALID_INPUT');
+      const payloadCopy = clone(payload), signature = canonical(payloadCopy);
+      return transact(tenantId, (state, currentTime) => {
+        const prior = state.keys.find((k) => k.tenantId === tenantId && k.key === key);
+        if (prior) {
+          if (prior.signature !== signature || prior.priority !== priority || prior.delayMs !== delayMs) return { error: fail('IDEMPOTENCY_CONFLICT') };
+          return { value: publicJob(find(state, tenantId, prior.id)) };
+        }
+        let id;
+        do { id = randomUUID(); } while (state.jobs.some((existing) => existing.id === id));
+        const job = { id, tenantId, key, payload: payloadCopy, priority, status: 'ready', attempts: 0, createdAt: currentTime,
+          availableAt: currentTime + delayMs, workerId: null, leaseToken: null, leaseUntil: null, lastError: null, sequence: ++state.sequence };
+        state.jobs.push(job);
+        state.keys.push({ tenantId, key, id: job.id, signature, priority, delayMs });
+        return { value: publicJob(job), changed: true };
+      });
+    },
+    async claim(arg) {
+      validateTenant(arg);
+      if (!validName(arg.workerId)) throw fail('INVALID_INPUT');
+      return transact(arg.tenantId, (state, currentTime) => {
+        const job = state.jobs.filter((j) => j.tenantId === arg.tenantId && j.status === 'ready' && j.availableAt <= currentTime)
+          .sort((a, b) => b.priority - a.priority || a.availableAt - b.availableAt || a.sequence - b.sequence)[0];
+        if (!job) return { value: null };
+        let token;
+        do { token = randomUUID(); } while (state.tokens.includes(token));
+        state.tokens.push(token);
+        job.status = 'leased'; job.attempts += 1; job.workerId = arg.workerId; job.leaseToken = token; job.leaseUntil = currentTime + leaseMs;
+        return { value: publicJob(job), changed: true };
+      });
+    },
+    async ack(arg) {
+      validateTenant(arg);
+      if (!validName(arg.jobId) || !validName(arg.workerId) || !validName(arg.leaseToken)) throw fail('INVALID_INPUT');
+      return transact(arg.tenantId, (state) => {
+        const job = find(state, arg.tenantId, arg.jobId);
+        if (!job) return { error: fail('NOT_FOUND') };
+        if (job.status === 'done' && job.receiptWorker === arg.workerId && job.receiptToken === arg.leaseToken) return { value: publicJob(job) };
+        if (job.status !== 'leased' || job.workerId !== arg.workerId || job.leaseToken !== arg.leaseToken) return { error: leaseError() };
+        job.status = 'done'; job.receiptWorker = arg.workerId; job.receiptToken = arg.leaseToken;
+        job.workerId = null; job.leaseToken = null; job.leaseUntil = null;
+        return { value: publicJob(job), changed: true };
+      });
+    },
+    async fail(arg) {
+      validateTenant(arg);
+      if (!validName(arg.jobId) || !validName(arg.workerId) || !validName(arg.leaseToken) || !validName(arg.error)) throw fail('INVALID_INPUT');
+      return transact(arg.tenantId, (state, currentTime) => {
+        const job = find(state, arg.tenantId, arg.jobId);
+        if (!job) return { error: fail('NOT_FOUND') };
+        if (job.status !== 'leased' || job.workerId !== arg.workerId || job.leaseToken !== arg.leaseToken) return { error: leaseError() };
+        job.status = job.attempts >= maxAttempts ? 'dead' : 'ready';
+        if (job.status === 'ready') job.availableAt = currentTime + backoffMs * (2 ** (job.attempts - 1));
+        job.lastError = arg.error; job.workerId = null; job.leaseToken = null; job.leaseUntil = null;
+        return { value: publicJob(job), changed: true };
+      });
+    },
+    async cancel(arg) {
+      validateTenant(arg);
+      if (!validName(arg.jobId)) throw fail('INVALID_INPUT');
+      return transact(arg.tenantId, (state) => {
+        const job = find(state, arg.tenantId, arg.jobId);
+        if (!job) return { error: fail('NOT_FOUND') };
+        if (job.status === 'cancelled') return { value: publicJob(job) };
+        if (job.status !== 'ready') return { error: fail('INVALID_STATE') };
+        job.status = 'cancelled';
+        return { value: publicJob(job), changed: true };
+      });
+    },
+    async list(arg) {
+      validateTenant(arg);
+      return transact(arg.tenantId, (state) => ({ value: state.jobs.filter((j) => j.tenantId === arg.tenantId).sort((a, b) => a.sequence - b.sequence).map(publicJob) }));
+    },
+  };
+}
diff --git a/tests/queue.acceptance.test.js b/tests/queue.acceptance.test.js
new file mode 100644
index 0000000..15f5233
--- /dev/null
+++ b/tests/queue.acceptance.test.js
@@ -0,0 +1,983 @@
+import {it, expect} from 'vitest';
+import {execFile} from 'node:child_process';
+import {mkdtemp, readdir, rm} from 'node:fs/promises';
+import {tmpdir} from 'node:os';
+import path from 'node:path';
+import {promisify} from 'node:util';
+import {openQueue} from '../src/queue.js';
+import {createFileStore, createMemoryStore} from '../lib/stores.js';
+
+const execFileAsync = promisify(execFile);
+const queueUrl = new URL('../src/queue.js', import.meta.url).href;
+const storesUrl = new URL('../lib/stores.js', import.meta.url).href;
+const JOB_KEYS = ['id', 'tenantId', 'key', 'payload', 'priority', 'status', 'attempts', 'createdAt', 'availableAt', 'workerId', 'leaseToken', 'leaseUntil', 'lastError'].sort();
+
+function makeClock(start = 0) {
+  const clock = {t: start, now: () => clock.t};
+  return clock;
+}
+
+// Counts CAS calls, can fail the next load/CAS before it reaches the inner store, and can run a hook before each CAS.
+function countingStore(inner) {
+  const store = {
+    casCalls: 0,
+    failLoads: 0,
+    failCas: 0,
+    beforeCas: null,
+    async load() {
+      if (store.failLoads > 0) {
+        store.failLoads -= 1;
+        throw new Error('EIO load');
+      }
+      return inner.load();
+    },
+    async compareAndSwap(version, state) {
+      store.casCalls += 1;
+      if (store.beforeCas) await store.beforeCas();
+      if (store.failCas > 0) {
+        store.failCas -= 1;
+        throw new Error('EIO cas');
+      }
+      return inner.compareAndSwap(version, state);
+    },
+  };
+  return store;
+}
+
+// Adds random async delay to every load and CAS. Seeded so runs are reproducible.
+function delayedStore(inner, random) {
+  const pause = () => new Promise((resolve) => setTimeout(resolve, Math.floor(random() * 3)));
+  return {
+    async load() {
+      await pause();
+      return inner.load();
+    },
+    async compareAndSwap(version, state) {
+      await pause();
+      return inner.compareAndSwap(version, state);
+    },
+  };
+}
+
+function seededRandom(seed) {
+  let state = seed >>> 0;
+  return () => {
+    state = (state + 0x6d2b79f5) >>> 0;
+    let t = state;
+    t = Math.imul(t ^ (t >>> 15), t | 1);
+    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+  };
+}
+
+function garbageStore(state) {
+  const store = {
+    casCalls: 0,
+    async load() {
+      return {version: 0, state};
+    },
+    async compareAndSwap() {
+      store.casCalls += 1;
+      return false;
+    },
+  };
+  return store;
+}
+
+async function failureOf(action) {
+  try {
+    await action();
+  } catch (error) {
+    return error;
+  }
+  return null;
+}
+
+async function expectFailure(action, code, label = code) {
+  const error = await failureOf(action);
+  expect(error, label).toBeInstanceOf(Error);
+  expect(error?.code, label).toBe(code);
+  return error;
+}
+
+function scramble(value) {
+  if (value !== null && typeof value === 'object') {
+    for (const key of Object.keys(value)) {
+      scramble(value[key]);
+      delete value[key];
+    }
+  }
+}
+
+async function runChild(body, now, file) {
+  const script = `const {openQueue} = await import(${JSON.stringify(queueUrl)});
+const {createFileStore} = await import(${JSON.stringify(storesUrl)});
+const queue = await openQueue({store: createFileStore(process.env.LQ_FILE), now: () => ${now}, leaseMs: 100000});
+${body}`;
+  const {stdout} = await execFileAsync(process.execPath, ['--input-type=module', '-e', script], {env: {...process.env, LQ_FILE: file}});
+  return JSON.parse(stdout);
+}
+
+it('[R-1][C-1] enqueue, claim and ack keep documented fields, lease values and nested payload', async () => {
+  const clock = makeClock(1000);
+  const queue = await openQueue({store: createMemoryStore(), now: clock.now, leaseMs: 1000});
+  const payload = {customer: {id: 'c-1', tags: ['a', 'b'], meta: {score: 1.5, active: true, note: null}}, items: [{sku: 'x', qty: 2}]};
+
+  const enqueued = await queue.enqueue({tenantId: 't', key: 'order-1', payload});
+  expect(Object.keys(enqueued).sort()).toEqual(JOB_KEYS);
+  expect(enqueued).toMatchObject({tenantId: 't', key: 'order-1', priority: 0, status: 'ready', attempts: 0, createdAt: 1000, availableAt: 1000, workerId: null, leaseToken: null, leaseUntil: null, lastError: null});
+  expect(enqueued.payload).toEqual(payload);
+
+  const delayed = await queue.enqueue({tenantId: 't', key: 'later', payload: {n: 2}, delayMs: 250});
+  expect(delayed).toMatchObject({status: 'ready', availableAt: 1250});
+
+  const claimed = await queue.claim({tenantId: 't', workerId: 'A'});
+  expect(claimed.id).toBe(enqueued.id);
+  expect(claimed).toMatchObject({status: 'leased', attempts: 1, workerId: 'A', leaseUntil: 2000});
+  expect(claimed.leaseToken.length).toBeGreaterThan(0);
+  expect(claimed.payload).toEqual(payload);
+
+  const acked = await queue.ack({tenantId: 't', jobId: enqueued.id, workerId: 'A', leaseToken: claimed.leaseToken});
+  expect(acked).toMatchObject({id: enqueued.id, status: 'done', attempts: 1, workerId: null, leaseToken: null, leaseUntil: null});
+  expect(acked.payload).toEqual(payload);
+
+  const listed = await queue.list({tenantId: 't'});
+  expect(listed.map((job) => job.id)).toEqual([enqueued.id, delayed.id]);
+  expect(listed[0]).toEqual(acked);
+  expect(listed[1]).toEqual(delayed);
+  for (const job of listed) expect(Object.keys(job).sort()).toEqual(JOB_KEYS);
+});
+
+it('[R-1][C-2] claim picks priority, then earliest availableAt, then commit order and skips jobs not yet due', async () => {
+  const clock = makeClock(0);
+  const enqueueAll = async (queue) => {
+    await queue.enqueue({tenantId: 't', key: 'a', payload: {}, priority: 0});
+    await queue.enqueue({tenantId: 't', key: 'b', payload: {}, priority: 5});
+    await queue.enqueue({tenantId: 't', key: 'c', payload: {}, priority: 5, delayMs: 0});
+    await queue.enqueue({tenantId: 't', key: 'd', payload: {}, priority: 9, delayMs: 500});
+    await queue.enqueue({tenantId: 't', key: 'e', payload: {}, priority: 0});
+  };
+  const claimKey = async (queue) => {
+    const job = await queue.claim({tenantId: 't', workerId: 'w'});
+    return job === null ? null : job.key;
+  };
+
+  const atZero = await openQueue({store: createMemoryStore(), now: clock.now});
+  await enqueueAll(atZero);
+  const zeroClaims = [];
+  for (let i = 0; i < 5; i += 1) zeroClaims.push(await claimKey(atZero));
+  expect(zeroClaims).toEqual(['b', 'c', 'a', 'e', null]);
+
+  clock.t = 500;
+  const atFiveHundred = await openQueue({store: createMemoryStore(), now: clock.now});
+  await enqueueAll(atFiveHundred);
+  const laterClaims = [];
+  for (let i = 0; i < 6; i += 1) laterClaims.push(await claimKey(atFiveHundred));
+  expect(laterClaims).toEqual(['d', 'b', 'c', 'a', 'e', null]);
+});
+
+it('[R-1][C-3] fail applies exponential backoff, dead-letters at maxAttempts and rejects blank errors', async () => {
+  const clock = makeClock(0);
+  const queue = await openQueue({store: createMemoryStore(), now: clock.now, leaseMs: 5000, maxAttempts: 3, backoffMs: 100});
+  const job = await queue.enqueue({tenantId: 't', key: 'k', payload: {}});
+
+  clock.t = 1000;
+  const first = await queue.claim({tenantId: 't', workerId: 'A'});
+  await expectFailure(() => queue.fail({tenantId: 't', jobId: job.id, workerId: 'A', leaseToken: first.leaseToken, error: ''}), 'INVALID_INPUT', 'empty error');
+  await expectFailure(() => queue.fail({tenantId: 't', jobId: job.id, workerId: 'A', leaseToken: first.leaseToken, error: '   '}), 'INVALID_INPUT', 'blank error');
+  expect(await queue.list({tenantId: 't'})).toEqual([first]);
+
+  const failed1 = await queue.fail({tenantId: 't', jobId: job.id, workerId: 'A', leaseToken: first.leaseToken, error: 'boom-1'});
+  expect(failed1).toMatchObject({status: 'ready', attempts: 1, availableAt: 1100, workerId: null, leaseToken: null, leaseUntil: null, lastError: 'boom-1'});
+
+  clock.t = 1099;
+  expect(await queue.claim({tenantId: 't', workerId: 'B'})).toBeNull();
+
+  clock.t = 1100;
+  const second = await queue.claim({tenantId: 't', workerId: 'B'});
+  expect(second).toMatchObject({id: job.id, attempts: 2, workerId: 'B'});
+  expect(second.leaseToken).not.toBe(first.leaseToken);
+  const failed2 = await queue.fail({tenantId: 't', jobId: job.id, workerId: 'B', leaseToken: second.leaseToken, error: 'boom-2'});
+  expect(failed2).toMatchObject({status: 'ready', attempts: 2, availableAt: 1300, leaseToken: null, lastError: 'boom-2'});
+
+  clock.t = 1300;
+  const third = await queue.claim({tenantId: 't', workerId: 'C'});
+  expect(third).toMatchObject({id: job.id, attempts: 3, workerId: 'C'});
+  const failed3 = await queue.fail({tenantId: 't', jobId: job.id, workerId: 'C', leaseToken: third.leaseToken, error: 'boom-3'});
+  expect(failed3).toMatchObject({status: 'dead', attempts: 3, workerId: null, leaseToken: null, lastError: 'boom-3'});
+
+  clock.t = 1_000_000;
+  expect(await queue.claim({tenantId: 't', workerId: 'D'})).toBeNull();
+
+  const quick = await openQueue({store: createMemoryStore(), now: clock.now, leaseMs: 5000, maxAttempts: 1, backoffMs: 0});
+  await quick.enqueue({tenantId: 't', key: 'once', payload: {}});
+  const quickClaim = await quick.claim({tenantId: 't', workerId: 'Q'});
+  const quickFailed = await quick.fail({tenantId: 't', jobId: quickClaim.id, workerId: 'Q', leaseToken: quickClaim.leaseToken, error: 'once'});
+  expect(quickFailed).toMatchObject({status: 'dead', attempts: 1, lastError: 'once'});
+});
+
+it('[R-1][C-4] idempotent enqueue replays original id and current state, rejects changed parameters, scopes keys per tenant', async () => {
+  const clock = makeClock(0);
+  const store = createMemoryStore();
+  const first = await openQueue({store, now: clock.now, leaseMs: 1000});
+  const original = await first.enqueue({tenantId: 't', key: 'K', payload: {a: 1, b: [1, 2]}, priority: 3, delayMs: 50});
+
+  clock.t = 50;
+  const claimed = await first.claim({tenantId: 't', workerId: 'w'});
+  await first.ack({tenantId: 't', jobId: original.id, workerId: 'w', leaseToken: claimed.leaseToken});
+
+  const reopened = await openQueue({store, now: clock.now, leaseMs: 1000});
+  const versionBefore = store.inspect().version;
+  const replay = await reopened.enqueue({tenantId: 't', key: 'K', payload: {b: [1, 2], a: 1}, priority: 3, delayMs: 50});
+  expect(replay.id).toBe(original.id);
+  expect(replay.status).toBe('done');
+  expect(store.inspect().version).toBe(versionBefore);
+
+  await expectFailure(() => reopened.enqueue({tenantId: 't', key: 'K', payload: {b: [2, 1], a: 1}, priority: 3, delayMs: 50}), 'IDEMPOTENCY_CONFLICT', 'array order changed');
+  await expectFailure(() => reopened.enqueue({tenantId: 't', key: 'K', payload: {a: 1, b: [1, 2]}, priority: 4, delayMs: 50}), 'IDEMPOTENCY_CONFLICT', 'priority changed');
+  await expectFailure(() => reopened.enqueue({tenantId: 't', key: 'K', payload: {a: 1, b: [1, 2]}, priority: 3, delayMs: 0}), 'IDEMPOTENCY_CONFLICT', 'delayMs changed');
+
+  const other = await reopened.enqueue({tenantId: 't', key: 'K2', payload: {x: 1}, priority: 0, delayMs: 0});
+  const cancelled = await reopened.cancel({tenantId: 't', jobId: other.id});
+  expect(cancelled.status).toBe('cancelled');
+  const replayCancelled = await reopened.enqueue({tenantId: 't', key: 'K2', payload: {x: 1}, priority: 0, delayMs: 0});
+  expect(replayCancelled).toMatchObject({id: other.id, status: 'cancelled'});
+
+  const otherTenant = await reopened.enqueue({tenantId: 'u', key: 'K', payload: {a: 1, b: [1, 2]}, priority: 3, delayMs: 50});
+  expect(otherTenant.id).not.toBe(original.id);
+  expect(otherTenant.tenantId).toBe('u');
+  expect((await reopened.list({tenantId: 't'})).map((job) => job.id)).toEqual([original.id, other.id]);
+});
+
+it('[R-1][C-5] ack replay with original owner and token returns the done job without CAS; other pairs get STALE_LEASE', async () => {
+  const clock = makeClock(0);
+  const store = countingStore(createMemoryStore());
+  const queue = await openQueue({store, now: clock.now, leaseMs: 1000});
+  const job = await queue.enqueue({tenantId: 't', key: 'k', payload: {}});
+  const claimed = await queue.claim({tenantId: 't', workerId: 'A'});
+  const done = await queue.ack({tenantId: 't', jobId: job.id, workerId: 'A', leaseToken: claimed.leaseToken});
+  const before = await queue.list({tenantId: 't'});
+
+  const casBefore = store.casCalls;
+  const replay = await queue.ack({tenantId: 't', jobId: job.id, workerId: 'A', leaseToken: claimed.leaseToken});
+  expect(replay).toEqual(done);
+  expect(store.casCalls).toBe(casBefore);
+
+  await expectFailure(() => queue.ack({tenantId: 't', jobId: job.id, workerId: 'B', leaseToken: claimed.leaseToken}), 'STALE_LEASE', 'other worker');
